import {statusLabel} from './report-metrics.js';
export {statusLabel,summarize,csvCell,reportCsv} from './report-metrics.js';
export {mountReport} from './report-view.js';
export function mountAudit(root,client,eventId,active){
 const panel=document.createElement('div');panel.className='panel';panel.innerHTML='<h3>ประวัติการดำเนินการ</h3><p class="sub">ข้อมูลบันทึกโดยระบบ แสดงชุดละ 50 รายการตามรหัสรายการ เวลาในแต่ละชุดเรียงจากใหม่ไปเก่า</p><button>โหลดประวัติ</button><p role="status"></p><div class="audit-items"></div>';root.append(panel);
 const button=panel.querySelector('button'),status=panel.querySelector('[role=status]'),list=panel.querySelector('.audit-items');let after;
 button.onclick=async()=>{button.disabled=true;try{const page=await client.loadAudit(eventId,after);if(!active()||!panel.isConnected)return;list.replaceChildren();const sorted=page.items.sort((a,b)=>(b.at?.toMillis?.()||0)-(a.at?.toMillis?.()||0));for(const item of sorted){const row=document.createElement('article');row.className='audit-row';const title=document.createElement('strong');title.textContent=({saveRegistrationSchedule:'ตั้งเวลาเปิด–ปิดรับสมัคร',checkinSignature:'บันทึกลายเซ็นผู้เข้าร่วม',deleteApplication:'ย้ายใบสมัครไปถังขยะ',restoreApplication:'กู้คืนใบสมัคร',editApplication:'แก้ไขข้อมูลผู้สมัคร',editEvent:'แก้ไขกิจกรรม',enroll:'สมัครกิจกรรม',approve:'อนุมัติ',reject:'ปฏิเสธ',cancel:'ยกเลิก',checkin:'เช็คอิน',assign:'มอบหมายสิทธิ์เฉพาะกิจกรรม',assignDelegate:'มอบหมายงานทั้งระบบ',createEvent:'สร้างกิจกรรม',pauseRegistration:'ปรับการรับสมัคร',pauseCheckin:'ปรับการเช็คอิน'})[item.action]||item.action;const detail=document.createElement('p');detail.className='sub';detail.textContent=(item.at?.toDate?.().toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})||'ไม่ระบุเวลา')+' · ผู้ดำเนินการ '+item.actorUid+(item.applicationId?' · ใบสมัคร '+item.applicationId:'')+(item.from?' · '+(statusLabel[item.from]||item.from)+' → '+(statusLabel[item.to]||item.to):'');row.append(title,detail);if(item.action==='editApplication'&&item.before&&item.after){const changes=document.createElement('p');changes.textContent='ชื่อ: '+item.before.displayName+' → '+item.after.displayName+' · เบอร์โทร: '+(item.before.phone||'ไม่มีข้อมูล')+' → '+item.after.phone;row.append(changes)}list.append(row)}status.textContent='พบ '+page.items.length+' รายการในชุดนี้';after=page.next;button.textContent=after?'ชุดถัดไป':'โหลดใหม่';}catch(error){if(active())status.textContent=error.message||'โหลดประวัติไม่ได้'}finally{button.disabled=false}};
}
